package config

import (
	"time"

	"github.com/ManuelGarciaF/vialis-motor/internal/lines"
	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/demand"
	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/revenue"
	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/traveltime"
)

// This file holds the parameters of the simulation model. They are constants on
// purpose: each one changes the numbers the engine reports, so changing one is a
// change to the model that belongs in a reviewable commit, not in the
// environment of whoever happens to start the process. Deployment settings and
// secret provider credentials — database URL, listen address and TomTom API key
// — are read from the environment in config.go.
//
// One model constant lives next to the code that enforces it rather than here,
// because the domain packages must not depend on this one:
// route.endpointToleranceMeters (20 m, how far a pathToNext endpoint may sit
// from its stop).

const (
	// AccessRadiusMeters is the maximum walking distance between a stop and a
	// cell's point of maximum concurrence. Cells farther than this are not
	// assigned to the stop at all.
	AccessRadiusMeters = 800.0

	// RevenueCaptureFactor is the share of potential demand assumed to actually
	// board the line. At 1 the engine reports the ceiling, which is what a
	// proposal should be judged against before any operational discount.
	RevenueCaptureFactor = 1.0

	// RegisteredCardShare is the share of trips paid with a registered SUBE
	// card, which is charged the lower band of the tariff table.
	RegisteredCardShare = 1.0
)

// HTTP server timeouts. SimulationTimeout sits below WriteTimeout so a slow
// simulation is answered with a timeout status instead of having its connection
// closed mid-response. Raise both together when comparing long suburban routes.
const (
	ReadHeaderTimeout = 5 * time.Second
	ReadTimeout       = 10 * time.Second
	WriteTimeout      = 30 * time.Second
	IdleTimeout       = 60 * time.Second
	SimulationTimeout = 25 * time.Second

	// DatabaseConnectTimeout bounds the startup connectivity check and the
	// graceful shutdown that mirrors it.
	DatabaseConnectTimeout = 10 * time.Second
)

// AccessibilityCalculator converts the distance between a stop and a cell into a
// 0-1 weight. demand.QuadraticAccessibility is the documented alternative: it
// applies the same ratio squared, penalising distant cells harder.
func AccessibilityCalculator() demand.AccessibilityCalculator {
	return demand.LinearAccessibility{}
}

// TravelTimePolicy controls how existing GTFS routes are chosen as a reference
// for each segment: the corridors tried in order, how many routes a corridor
// needs before it wins, and the bounds outside which a reference's commercial
// speed is discarded as a data error.
func TravelTimePolicy() traveltime.Policy {
	return traveltime.Policy{
		ReferenceRadiiMeters:      []float64{100, 300, 800},
		MinimumReferenceRoutes:    3,
		DirectionToleranceDegrees: 60,
		MinimumCommercialSpeedKPH: 2,
		MaximumCommercialSpeedKPH: 80,
	}
}

// Reading the stored GTFS lines back out, for GET /lines and /lines/{id}.
const (
	// LinesAlignmentToleranceMeters is deliberately far wider than the 20 m
	// route.Validate demands: it decides whether a stored path endpoint is
	// recognisably the same place as its stop, not whether a caller sent
	// coherent geometry. It applies only to the engine's own stored geometry,
	// never to caller input. Raise it only if the GTFS feed places shape
	// boundaries further from its stops.
	LinesAlignmentToleranceMeters = 250.0

	// LinesDefaultPageSize is how many lines a listing returns when the caller
	// does not ask for a size.
	LinesDefaultPageSize = 50

	// LinesMaximumPageSize bounds one response so listing the AMBA feed cannot
	// be turned into a full table dump by a single request. It must stay at or
	// above LinesDefaultPageSize, or a listing would silently return fewer
	// lines than configured; TestLinesPolicyIsCoherent enforces that.
	LinesMaximumPageSize = 200
)

// LinesPolicy returns the rules applied when exporting stored lines.
func LinesPolicy() lines.Policy {
	return lines.Policy{
		AlignmentToleranceMeters: LinesAlignmentToleranceMeters,
		DefaultPageSize:          LinesDefaultPageSize,
		MaximumPageSize:          LinesMaximumPageSize,
	}
}

// RevenuePolicy turns potential demand into potential revenue.
func RevenuePolicy() revenue.Policy {
	return revenue.Policy{
		CaptureFactor:       RevenueCaptureFactor,
		RegisteredCardShare: RegisteredCardShare,
	}
}

package route

import (
	"fmt"
	"math"
	"strings"
)

const (
	endpointToleranceMeters = 20.0
	earthRadiusMeters       = 6371008.8
)

// ValidationError reports an invalid route input.
type ValidationError struct {
	Field   string
	Message string
}

func (err *ValidationError) Error() string {
	return fmt.Sprintf("%s: %s", err.Field, err.Message)
}

// Rooted returns a copy of the error whose field path starts at root instead
// of the "route" prefix Validate uses.
//
// A caller validating more than one route in the same request needs the error
// to say which of them failed, and "route.stops[3].id" cannot.
func (err *ValidationError) Rooted(root string) *ValidationError {
	field, found := strings.CutPrefix(err.Field, "route")
	if found {
		field = root + field
	} else {
		field = root + "." + err.Field
	}
	return &ValidationError{Field: field, Message: err.Message}
}

// Validate checks the complete route contract used by every estimator.
func Validate(input Route) error {
	if input.Jurisdiction != JurisdictionCABA &&
		input.Jurisdiction != JurisdictionProvince &&
		input.Jurisdiction != JurisdictionNational {
		return &ValidationError{
			Field:   "route.jurisdiction",
			Message: "must be caba, province, or national",
		}
	}
	if len(input.Stops) < 2 {
		return &ValidationError{
			Field:   "route.stops",
			Message: "must contain at least two stops",
		}
	}

	stopIDs := make(map[string]struct{}, len(input.Stops))
	for index, stop := range input.Stops {
		field := fmt.Sprintf("route.stops[%d]", index)
		stopID := strings.TrimSpace(stop.ID)
		if stopID == "" {
			return &ValidationError{
				Field:   field + ".id",
				Message: "must not be empty",
			}
		}
		if _, exists := stopIDs[stopID]; exists {
			return &ValidationError{
				Field:   field + ".id",
				Message: "must be unique within the route",
			}
		}
		stopIDs[stopID] = struct{}{}
		if err := validatePosition(field+".position", stop.Position); err != nil {
			return err
		}
	}

	for index := range input.Stops {
		stop := input.Stops[index]
		field := fmt.Sprintf("route.stops[%d].pathToNext", index)
		if index == len(input.Stops)-1 {
			if stop.PathToNext != nil {
				return &ValidationError{
					Field:   field,
					Message: "must be omitted for the last stop",
				}
			}
			continue
		}
		if stop.PathToNext == nil {
			return &ValidationError{
				Field:   field,
				Message: "is required except for the last stop",
			}
		}
		if err := validatePath(
			field,
			*stop.PathToNext,
			stop.Position,
			input.Stops[index+1].Position,
		); err != nil {
			return err
		}
	}
	return nil
}

func validatePath(
	field string,
	path LineString,
	origin Position,
	destination Position,
) error {
	if len(path.Positions) < 2 {
		return &ValidationError{
			Field:   field + ".coordinates",
			Message: "must contain at least two positions",
		}
	}
	for index, position := range path.Positions {
		if err := validatePosition(
			fmt.Sprintf("%s.coordinates[%d]", field, index),
			position,
		); err != nil {
			return err
		}
	}

	first := path.Positions[0]
	last := path.Positions[len(path.Positions)-1]
	firstToOrigin := DistanceMeters(first, origin)
	lastToDestination := DistanceMeters(last, destination)
	firstToDestination := DistanceMeters(first, destination)
	lastToOrigin := DistanceMeters(last, origin)
	if firstToDestination <= endpointToleranceMeters &&
		lastToOrigin <= endpointToleranceMeters &&
		firstToDestination+lastToOrigin <
			firstToOrigin+lastToDestination {
		return &ValidationError{
			Field:   field,
			Message: "must be ordered from the current stop to the next stop",
		}
	}
	if firstToOrigin > endpointToleranceMeters {
		return &ValidationError{
			Field:   field + ".coordinates[0]",
			Message: "must be within 20 meters of the current stop",
		}
	}
	if lastToDestination > endpointToleranceMeters {
		return &ValidationError{
			Field: fmt.Sprintf(
				"%s.coordinates[%d]",
				field,
				len(path.Positions)-1,
			),
			Message: "must be within 20 meters of the next stop",
		}
	}

	var lengthMeters float64
	for index := 0; index < len(path.Positions)-1; index++ {
		lengthMeters += DistanceMeters(
			path.Positions[index],
			path.Positions[index+1],
		)
	}
	if lengthMeters <= 0 {
		return &ValidationError{
			Field:   field,
			Message: "must have a positive length",
		}
	}
	return nil
}

func validatePosition(field string, position Position) error {
	if !finite(position.Latitude) ||
		position.Latitude < -90 ||
		position.Latitude > 90 {
		return &ValidationError{
			Field:   field + ".latitude",
			Message: "must be between -90 and 90",
		}
	}
	if !finite(position.Longitude) ||
		position.Longitude < -180 ||
		position.Longitude > 180 {
		return &ValidationError{
			Field:   field + ".longitude",
			Message: "must be between -180 and 180",
		}
	}
	return nil
}

// DistanceMeters calculates the great-circle distance between two positions.
func DistanceMeters(left, right Position) float64 {
	leftLatitude := radians(left.Latitude)
	rightLatitude := radians(right.Latitude)
	latitudeDelta := rightLatitude - leftLatitude
	longitudeDelta := radians(right.Longitude - left.Longitude)

	sineLatitude := math.Sin(latitudeDelta / 2)
	sineLongitude := math.Sin(longitudeDelta / 2)
	haversine := sineLatitude*sineLatitude +
		math.Cos(leftLatitude)*math.Cos(rightLatitude)*
			sineLongitude*sineLongitude
	haversine = math.Min(1, math.Max(0, haversine))
	return 2 * earthRadiusMeters * math.Asin(math.Sqrt(haversine))
}

func radians(degrees float64) float64 {
	return degrees * math.Pi / 180
}

func finite(value float64) bool {
	return !math.IsNaN(value) && !math.IsInf(value, 0)
}

package simulation

import (
	"context"
	"fmt"

	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/demand"
	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/revenue"
	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/route"
	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/traveltime"
)

// DemandEstimator calculates potential demand for a validated route.
type DemandEstimator interface {
	Estimate(ctx context.Context, input route.Route) (demand.Result, error)
}

// TravelTimeEstimator measures the route and estimates commercial travel time.
type TravelTimeEstimator interface {
	Estimate(ctx context.Context, input route.Route) (traveltime.Result, error)
}

// RevenueEstimator calculates potential fare revenue for a simulated route.
type RevenueEstimator interface {
	Estimate(context.Context, route.Route, demand.Result, traveltime.Result) (revenue.Result, error)
}

// Service executes every simulation estimator.
type Service struct {
	demandEstimator     DemandEstimator
	travelTimeEstimator TravelTimeEstimator
	revenueEstimator    RevenueEstimator
}

// NewService creates the simulation orchestrator.
func NewService(
	demandEstimator DemandEstimator,
	travelTimeEstimator TravelTimeEstimator,
	revenueEstimator RevenueEstimator,
) *Service {
	return &Service{
		demandEstimator:     demandEstimator,
		travelTimeEstimator: travelTimeEstimator,
		revenueEstimator:    revenueEstimator,
	}
}

// Simulate validates and calculates all metrics for one ordered route.
func (service *Service) Simulate(
	ctx context.Context,
	input route.Route,
) (Result, error) {
	if err := route.Validate(input); err != nil {
		return Result{}, err
	}

	demandResult, err := service.demandEstimator.Estimate(ctx, input)
	if err != nil {
		return Result{}, fmt.Errorf("estimate demand: %w", err)
	}
	travelTimeResult, err := service.travelTimeEstimator.Estimate(ctx, input)
	if err != nil {
		return Result{}, fmt.Errorf("estimate travel time: %w", err)
	}
	revenueResult, err := service.revenueEstimator.Estimate(
		ctx,
		input,
		demandResult,
		travelTimeResult,
	)
	if err != nil {
		return Result{}, fmt.Errorf("estimate revenue: %w", err)
	}

	return Result{
		Global: GlobalResult{
			Demand: DemandTotals{
				GrossDemand:     demandResult.GrossDemand,
				PotentialDemand: demandResult.PotentialDemand,
			},
			Revenue: RevenueTotals{
				Jurisdiction:          revenueResult.Jurisdiction,
				CaptureFactor:         revenueResult.CaptureFactor,
				RegisteredCardShare:   revenueResult.RegisteredCardShare,
				PotentialRevenueCents: revenueResult.PotentialRevenueCents,
			},
			Metrics: MetricsTotals{
				TotalDistanceMeters: travelTimeResult.TotalDistanceMeters,
				TravelTime: TravelTimeTotals{
					OffPeakSeconds: travelTimeResult.OffPeakSeconds,
					TypicalSeconds: travelTimeResult.TypicalSeconds,
					PeakSeconds:    travelTimeResult.PeakSeconds,
					Confidence:     travelTimeResult.Confidence,
				},
			},
		},
		ByStop: stopResults(input, demandResult, travelTimeResult, revenueResult),
	}, nil
}

package simulation

import (
	"context"
	"errors"
	"fmt"

	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/route"
	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/traveltime"
	"golang.org/x/sync/errgroup"
)

// ComparisonInput is the pair of routes to evaluate against each other.
//
// Both are complete routes rather than a description of what changed: the
// engine evaluates routes, it does not edit them, so deciding what a proposal
// looks like stays with the caller.
type ComparisonInput struct {
	Baseline Route `json:"baseline"`
	Proposed Route `json:"proposed"`
}

// Comparison is both simulations together with how the proposal moved each
// metric.
type Comparison struct {
	Baseline Result `json:"baseline"`
	Proposed Result `json:"proposed"`
	Delta    Delta  `json:"delta"`
}

// Delta is the difference between the two simulations.
type Delta struct {
	StopCount IntChange    `json:"stopCount"`
	Demand    DemandDelta  `json:"demand"`
	Revenue   RevenueDelta `json:"revenue"`
	Metrics   MetricsDelta `json:"metrics"`
}

// DemandDelta is how the proposal moved the demand the route could carry.
type DemandDelta struct {
	GrossDemand     Change `json:"grossDemand"`
	PotentialDemand Change `json:"potentialDemand"`
}

// RevenueDelta is how the proposal moved the expected fare revenue.
type RevenueDelta struct {
	PotentialRevenueCents Change `json:"potentialRevenueCents"`
}

// MetricsDelta is how the proposal moved the length and duration of the route.
type MetricsDelta struct {
	TotalDistanceMeters Change          `json:"totalDistanceMeters"`
	TravelTime          TravelTimeDelta `json:"travelTime"`
}

// TravelTimeDelta is how the proposal moved commercial travel time.
type TravelTimeDelta struct {
	OffPeakSeconds IntChange        `json:"offPeakSeconds"`
	TypicalSeconds IntChange        `json:"typicalSeconds"`
	PeakSeconds    IntChange        `json:"peakSeconds"`
	Confidence     ConfidenceChange `json:"confidence"`
}

// ConfidenceChange reports both confidence levels and subtracts nothing: the
// levels are ordinal labels, so the distance between two of them has no
// meaning to report.
type ConfidenceChange struct {
	Baseline traveltime.Confidence `json:"baseline"`
	Proposed traveltime.Confidence `json:"proposed"`
}

// Compare simulates both routes and reports the difference between them.
func (service *Service) Compare(
	ctx context.Context,
	input ComparisonInput,
) (Comparison, error) {
	if err := validateComparison(input); err != nil {
		return Comparison{}, err
	}

	// Both simulations spend nearly all of their time inside PostGIS, so
	// running them together turns the wait into the longer of the two rather
	// than their sum. The shared context cancels the surviving query as soon as
	// one of them fails, instead of paying for an answer already discarded.
	group, groupContext := errgroup.WithContext(ctx)
	var baseline, proposed Result
	group.Go(func() error {
		var err error
		baseline, err = service.Simulate(groupContext, input.Baseline)
		if err != nil {
			return fmt.Errorf("simulate baseline: %w", err)
		}
		return nil
	})
	group.Go(func() error {
		var err error
		proposed, err = service.Simulate(groupContext, input.Proposed)
		if err != nil {
			return fmt.Errorf("simulate proposed: %w", err)
		}
		return nil
	})
	if err := group.Wait(); err != nil {
		return Comparison{}, err
	}

	return Comparison{
		Baseline: baseline,
		Proposed: proposed,
		Delta:    newDelta(input, baseline, proposed),
	}, nil
}

// validateComparison checks both routes before either simulation starts, so an
// invalid request cannot spend minutes of database work first. Reporting the
// baseline ahead of the proposal keeps the answer deterministic when both are
// invalid.
func validateComparison(input ComparisonInput) error {
	if err := rootedValidation(input.Baseline, "baseline"); err != nil {
		return err
	}
	if err := rootedValidation(input.Proposed, "proposed"); err != nil {
		return err
	}

	// Every other policy input is shared configuration, so the jurisdiction is
	// the only way a caller can ask to compare results priced under different
	// tariff authorities.
	if input.Baseline.Jurisdiction != input.Proposed.Jurisdiction {
		return &route.ValidationError{
			Field: "proposed.jurisdiction",
			Message: "must match the baseline jurisdiction: results calculated " +
				"under different tariff authorities are not comparable",
		}
	}
	return nil
}

func rootedValidation(input Route, root string) error {
	err := route.Validate(input)
	if err == nil {
		return nil
	}
	var validationError *route.ValidationError
	if errors.As(err, &validationError) {
		return validationError.Rooted(root)
	}
	return err
}

func newDelta(input ComparisonInput, baseline, proposed Result) Delta {
	baselineGlobal := baseline.Global
	proposedGlobal := proposed.Global
	return Delta{
		StopCount: newIntChange(
			int64(len(input.Baseline.Stops)),
			int64(len(input.Proposed.Stops)),
		),
		Demand: DemandDelta{
			GrossDemand: newChange(
				baselineGlobal.Demand.GrossDemand,
				proposedGlobal.Demand.GrossDemand,
			),
			PotentialDemand: newChange(
				baselineGlobal.Demand.PotentialDemand,
				proposedGlobal.Demand.PotentialDemand,
			),
		},
		Revenue: RevenueDelta{
			PotentialRevenueCents: newChange(
				baselineGlobal.Revenue.PotentialRevenueCents,
				proposedGlobal.Revenue.PotentialRevenueCents,
			),
		},
		Metrics: MetricsDelta{
			TotalDistanceMeters: newChange(
				baselineGlobal.Metrics.TotalDistanceMeters,
				proposedGlobal.Metrics.TotalDistanceMeters,
			),
			TravelTime: TravelTimeDelta{
				OffPeakSeconds: newIntChange(
					baselineGlobal.Metrics.TravelTime.OffPeakSeconds,
					proposedGlobal.Metrics.TravelTime.OffPeakSeconds,
				),
				TypicalSeconds: newIntChange(
					baselineGlobal.Metrics.TravelTime.TypicalSeconds,
					proposedGlobal.Metrics.TravelTime.TypicalSeconds,
				),
				PeakSeconds: newIntChange(
					baselineGlobal.Metrics.TravelTime.PeakSeconds,
					proposedGlobal.Metrics.TravelTime.PeakSeconds,
				),
				Confidence: ConfidenceChange{
					Baseline: baselineGlobal.Metrics.TravelTime.Confidence,
					Proposed: proposedGlobal.Metrics.TravelTime.Confidence,
				},
			},
		},
	}
}

