	CacheHits            int            `json:"cacheHits"`
	GraphMatch           *matchReport   `json:"graphMatch,omitempty"`
	Duration             time.Duration  `json:"-"`
	DurationMillis       int64          `json:"durationMillis"`
	Tiles                []tile         `json:"tiles"`
}

type tileStats struct {
	bytes                int64
	features             int
	lineParts            int
	closures             int
	featuresWithoutSpeed int
	minimumSpeed         float64
	maximumSpeed         float64
	totalSpeed           float64
	speedCount           int
	roadTypes            map[string]int
	roadCategories       map[string]int
	roadSubcategories    map[string]int
	roadCoverage         map[string]int
}

func main() {
	if err := run(context.Background(), os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "tomtom-spike: %v\n", err)
		os.Exit(1)
	}
}

func run(ctx context.Context, args []string) error {
	options, err := parseOptions(args)
	if err != nil {
		return err
	}

	cfg := config.FromEnv()
	apiKey := cfg.TomTomAPIKey
	if apiKey == "" {
		return errors.New("TOMTOM_API_KEY is empty; export .env or run through direnv")
	}

	var matcher *trafficMatcher
	if options.matchDatabase {
		matcher, err = newTrafficMatcher(ctx, cfg.DatabaseURL)
		if err != nil {
			return err
		}
		defer matcher.Close(ctx)
	}

	var areaGeometry []byte
	if options.areaFile != "" {
		if matcher == nil {
			return errors.New("-area-file requires -match-db=true")
		}
		areaGeometry, err = loadAreaGeometry(options.areaFile, options.areaID)
		if err != nil {
			return err
		}
	}

	client := &http.Client{Timeout: options.timeout}
	result := report{
		GeneratedAt: time.Now().UTC(),
		Margin:      options.margin,
		Results:     make([]zoomReport, 0, len(options.zooms)),
	}
	if len(areaGeometry) != 0 {
		result.Area = &areaDescription{File: options.areaFile, FeatureID: options.areaID}
	} else {
		result.Center = &center{Latitude: options.latitude, Longitude: options.longitude}
		result.Radius = options.radius
	}

	for _, zoom := range options.zooms {
		var tiles []tile
		if len(areaGeometry) != 0 {
			tiles, err = matcher.TilesForArea(ctx, areaGeometry, zoom)
		} else {
			tiles, err = tilesAround(options.latitude, options.longitude, options.radius, zoom)
		}
		if err != nil {
			return fmt.Errorf("zoom %d: %w", zoom, err)
		}
		if len(tiles) > options.maxTiles {
			return fmt.Errorf(
				"zoom %d needs %d tiles, above -max-tiles=%d",
				zoom,
				len(tiles),
				options.maxTiles,
			)
		}

		startedAt := time.Now()
		zoomResult := newZoomReport(zoom, options.latitude, tiles)
		var trafficSegments []trafficSegment
		for _, tile := range tiles {
			data, cacheHit, err := loadOrFetchTile(
				ctx,
				client,
				apiKey,
				options.margin,
				tile,
				options.outputDir,
			)
			if err != nil {
				return err
			}
			if cacheHit {
				zoomResult.CacheHits++
			}

			stats, segments, err := inspectTile(data, tile)
			if err != nil {
				return fmt.Errorf("decode tile %d/%d/%d: %w", tile.Z, tile.X, tile.Y, err)
			}
			zoomResult.add(stats)
			trafficSegments = append(trafficSegments, segments...)
		}
		if matcher != nil {
			var match matchReport
			if len(areaGeometry) != 0 && options.viewerDir != "" {
				match, err = matcher.MatchAreaWithViewer(
					ctx,
					areaGeometry,
					trafficSegments,
					options.viewerDir,
				)
			} else if len(areaGeometry) != 0 {
				match, err = matcher.MatchArea(ctx, areaGeometry, trafficSegments)
			} else {
				match, err = matcher.Match(
					ctx,
					options.latitude,
					options.longitude,
					options.radius,
					trafficSegments,
				)
			}
			if err != nil {
				return fmt.Errorf("match zoom %d against vialis.calles: %w", zoom, err)
			}
			zoomResult.GraphMatch = &match
		}
		zoomResult.Duration = time.Since(startedAt)
		zoomResult.DurationMillis = zoomResult.Duration.Milliseconds()
		zoomResult.finish()
		result.Results = append(result.Results, zoomResult)
	}

	if options.viewerDir != "" {
		if err := writeJSONFile(filepath.Join(options.viewerDir, "report.json"), result); err != nil {
			return err
		}
	}
	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ")
	return encoder.Encode(result)
}

func parseOptions(args []string) (options, error) {
	flags := flag.NewFlagSet("tomtom-spike", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	latitude := flags.Float64("lat", defaultLatitude, "center latitude")
	longitude := flags.Float64("lon", defaultLongitude, "center longitude")
	radius := flags.Float64("radius", defaultRadius, "probe radius in meters")
	zoomValues := flags.String("zooms", defaultZooms, "comma-separated zoom levels")
	margin := flags.Float64("margin", defaultMargin, "TomTom tile margin from 0 to 0.1")
	maxTiles := flags.Int("max-tiles", defaultMaxTiles, "maximum tiles allowed per zoom")
	outputDir := flags.String("output-dir", "", "optional read-through cache for raw PBF tiles")
	areaFile := flags.String("area-file", "", "optional Polygon/Feature/FeatureCollection GeoJSON")
	areaID := flags.String("area-id", "", "feature properties.id selected from -area-file")
	viewerDir := flags.String("viewer-dir", "", "optional directory for local map viewer files")
	matchDatabase := flags.Bool("match-db", true, "compare traffic geometries with vialis.calles")
	timeout := flags.Duration("timeout", 15*time.Second, "timeout for each tile request")
	if err := flags.Parse(args); err != nil {
		return options{}, err
	}
	if flags.NArg() != 0 {
		return options{}, fmt.Errorf("unexpected arguments: %s", strings.Join(flags.Args(), " "))
	}
	if *latitude < -85.05112878 || *latitude > 85.05112878 {
		return options{}, fmt.Errorf("-lat must be between -85.05112878 and 85.05112878")
	}
	if *longitude < -180 || *longitude > 180 {
		return options{}, fmt.Errorf("-lon must be between -180 and 180")
	}
	if *radius <= 0 {
		return options{}, fmt.Errorf("-radius must be positive")
	}
	if *margin < 0 || *margin > 0.1 {
		return options{}, fmt.Errorf("-margin must be between 0 and 0.1")
	}
	if *maxTiles <= 0 {
		return options{}, fmt.Errorf("-max-tiles must be positive")
	}
	if *timeout <= 0 {
		return options{}, fmt.Errorf("-timeout must be positive")
	}
	if *viewerDir != "" && *areaFile == "" {
		return options{}, fmt.Errorf("-viewer-dir requires -area-file")
	}
	zooms, err := parseZooms(*zoomValues)
	if err != nil {
		return options{}, err
	}
	return options{
		latitude:      *latitude,
		longitude:     *longitude,
		radius:        *radius,
		zooms:         zooms,
		margin:        *margin,
		maxTiles:      *maxTiles,
		outputDir:     *outputDir,
		areaFile:      *areaFile,
		areaID:        *areaID,
		viewerDir:     *viewerDir,
		matchDatabase: *matchDatabase,
		timeout:       *timeout,
	}, nil
}

func parseZooms(value string) ([]int, error) {
	seen := make(map[int]struct{})
	var zooms []int
	for _, raw := range strings.Split(value, ",") {
		zoom, err := strconv.Atoi(strings.TrimSpace(raw))
		if err != nil || zoom < 0 || zoom > 22 {
			return nil, fmt.Errorf("invalid zoom %q: expected integers from 0 to 22", raw)
		}
		if _, exists := seen[zoom]; exists {
			continue
		}
		seen[zoom] = struct{}{}
		zooms = append(zooms, zoom)
	}
	if len(zooms) == 0 {
		return nil, errors.New("-zooms must not be empty")
	}
	sort.Ints(zooms)
	return zooms, nil
}

func tilesAround(latitude, longitude, radiusMeters float64, zoom int) ([]tile, error) {
	const earthRadiusMeters = 6378137.0
	latitudeRadians := latitude * math.Pi / 180
	latitudeDelta := radiusMeters / earthRadiusMeters * 180 / math.Pi
	cosine := math.Cos(latitudeRadians)
	if math.Abs(cosine) < 1e-9 {
		return nil, errors.New("cannot calculate longitude extent near a pole")
	}
	longitudeDelta := radiusMeters / (earthRadiusMeters * cosine) * 180 / math.Pi

	minimumLatitude := math.Max(-85.05112878, latitude-latitudeDelta)
	maximumLatitude := math.Min(85.05112878, latitude+latitudeDelta)
	minimumLongitude := math.Max(-180, longitude-longitudeDelta)
	maximumLongitude := math.Min(180, longitude+longitudeDelta)
	if minimumLongitude > maximumLongitude {
		return nil, errors.New("probe bounds cross the antimeridian")
	}

	minimumX := longitudeToTileX(minimumLongitude, zoom)
	maximumX := longitudeToTileX(maximumLongitude, zoom)
	minimumY := latitudeToTileY(maximumLatitude, zoom)
	maximumY := latitudeToTileY(minimumLatitude, zoom)

	tiles := make([]tile, 0, (maximumX-minimumX+1)*(maximumY-minimumY+1))
	for y := minimumY; y <= maximumY; y++ {
		for x := minimumX; x <= maximumX; x++ {
			tiles = append(tiles, tile{X: x, Y: y, Z: zoom})
		}
	}
	return tiles, nil
}

func longitudeToTileX(longitude float64, zoom int) int {
	size := math.Exp2(float64(zoom))
	x := int(math.Floor((longitude + 180) / 360 * size))
	return max(0, min(int(size)-1, x))
}

func latitudeToTileY(latitude float64, zoom int) int {
	latitudeRadians := latitude * math.Pi / 180
	size := math.Exp2(float64(zoom))
	y := int(math.Floor((1 - math.Asinh(math.Tan(latitudeRadians))/math.Pi) / 2 * size))
	return max(0, min(int(size)-1, y))
}

func fetchTile(
	ctx context.Context,
	client *http.Client,
	apiKey string,
	margin float64,
	tile tile,
) ([]byte, error) {
	endpoint, err := url.Parse(fmt.Sprintf(
		"%s/traffic/map/4/tile/flow/absolute/%d/%d/%d.pbf",
		tomTomBaseURL,
		tile.Z,
		tile.X,
		tile.Y,
	))
	if err != nil {
		return nil, fmt.Errorf("build tile URL: %w", err)
	}
	query := endpoint.Query()
	query.Set("key", apiKey)
	query.Set("margin", strconv.FormatFloat(margin, 'f', -1, 64))
	query.Set("tags", "[road_type,traffic_level,traffic_road_coverage,left_hand_traffic,road_closure,road_category,road_subcategory]")
	endpoint.RawQuery = query.Encode()

	request, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint.String(), nil)
	if err != nil {
		return nil, fmt.Errorf("create request for tile %d/%d/%d: %w", tile.Z, tile.X, tile.Y, err)
	}
	response, err := client.Do(request)
	if err != nil {
		return nil, fmt.Errorf(
			"fetch tile %d/%d/%d: %s",
			tile.Z,
			tile.X,
			tile.Y,
			redactSecret(err.Error(), apiKey),
		)
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK {
		message, _ := io.ReadAll(io.LimitReader(response.Body, 4096))
		return nil, fmt.Errorf(
			"fetch tile %d/%d/%d: TomTom returned %s: %s",
			tile.Z,
			tile.X,
			tile.Y,
			response.Status,
			redactSecret(strings.TrimSpace(string(message)), apiKey),
		)
	}

	data, err := io.ReadAll(io.LimitReader(response.Body, maximumTileBytes+1))
	if err != nil {
		return nil, fmt.Errorf("read tile %d/%d/%d: %w", tile.Z, tile.X, tile.Y, err)
	}
	if len(data) > maximumTileBytes {
		return nil, fmt.Errorf("tile %d/%d/%d exceeds %d bytes", tile.Z, tile.X, tile.Y, maximumTileBytes)
	}
	return data, nil
}

func inspectTile(data []byte, tile tile) (tileStats, []trafficSegment, error) {
	layers, err := mvt.Unmarshal(data)
	if err != nil {
		return tileStats{}, nil, err
	}
	layers.ProjectToWGS84(maptile.New(uint32(tile.X), uint32(tile.Y), maptile.Zoom(tile.Z)))

	stats := tileStats{
		bytes:             int64(len(data)),
		minimumSpeed:      math.Inf(1),
		maximumSpeed:      math.Inf(-1),
		roadTypes:         make(map[string]int),
		roadCategories:    make(map[string]int),
		roadSubcategories: make(map[string]int),
		roadCoverage:      make(map[string]int),
	}
	var segments []trafficSegment
	for _, layer := range layers {
		if layer.Name != "Traffic flow" {
			continue
		}
		for featureIndex, feature := range layer.Features {
			stats.features++
			roadType := feature.Properties.MustString("road_type", "unknown")
			roadCategory := feature.Properties.MustString("road_category", "unknown")
			roadSubcategory := feature.Properties.MustString("road_subcategory", "unknown")
			stats.roadTypes[roadType]++
			stats.roadCategories[roadCategory]++
			stats.roadSubcategories[roadSubcategory]++
			coverage := feature.Properties.MustString("traffic_road_coverage", "unknown")
			stats.roadCoverage[coverage]++
			closure := feature.Properties.MustBool("road_closure", false)
			if closure {
				stats.closures++
			}
			speedValue, exists := feature.Properties["traffic_level"]
			speed, valid := numericValue(speedValue)
			if !exists || !valid {
				stats.featuresWithoutSpeed++
			} else {
				stats.minimumSpeed = math.Min(stats.minimumSpeed, speed)
				stats.maximumSpeed = math.Max(stats.maximumSpeed, speed)
				stats.totalSpeed += speed
				stats.speedCount++
			}

			appendLine := func(line orb.LineString) {
				if len(line) < 2 {
					return
				}
				stats.lineParts++
				segments = append(segments, trafficSegment{
					SourceID:        fmt.Sprintf("%d/%d/%d/%d", tile.Z, tile.X, tile.Y, featureIndex),
					Geometry:        line,
					RoadType:        roadType,
					RoadCategory:    roadCategory,
					RoadSubcategory: roadSubcategory,
					RoadCoverage:    coverage,
					SpeedKPH:        speed,
					HasSpeed:        exists && valid,
					Closure:         closure,
				})
			}
			switch geometry := feature.Geometry.(type) {
			case orb.LineString:
				appendLine(geometry)
			case orb.MultiLineString:
				for _, line := range geometry {
					appendLine(line)
				}
			}
		}
	}
	return stats, segments, nil
}

func redactSecret(message, secret string) string {
	if secret == "" {
		return message
	}
	message = strings.ReplaceAll(message, secret, "[REDACTED]")
	return strings.ReplaceAll(message, url.QueryEscape(secret), "[REDACTED]")
}

func numericValue(value any) (float64, bool) {
	switch value := value.(type) {
	case float64:
		return value, true
	case float32:
		return float64(value), true
	case int:
		return float64(value), true
	case int64:
		return float64(value), true
	case uint64:
		return float64(value), true
	default:
		return 0, false
	}
}

func newZoomReport(zoom int, latitude float64, tiles []tile) zoomReport {
	const earthCircumferenceMeters = 40075016.686
	return zoomReport{
		Zoom:                 zoom,
		ApproxTileWidthMeter: earthCircumferenceMeters * math.Cos(latitude*math.Pi/180) / math.Exp2(float64(zoom)),
		TileCount:            len(tiles),
		RoadTypes:            make(map[string]int),
		RoadCategories:       make(map[string]int),
		RoadSubcategories:    make(map[string]int),
		RoadCoverage:         make(map[string]int),
		Tiles:                tiles,
	}
}

func (report *zoomReport) add(stats tileStats) {
	report.ResponseBytes += stats.bytes
	report.TrafficFeatures += stats.features
	report.LineParts += stats.lineParts
	report.Closures += stats.closures
	report.FeaturesWithoutSpeed += stats.featuresWithoutSpeed
	for value, count := range stats.roadTypes {
		report.RoadTypes[value] += count
	}
	for value, count := range stats.roadCategories {
		report.RoadCategories[value] += count
	}
	for value, count := range stats.roadSubcategories {
		report.RoadSubcategories[value] += count
	}
	for value, count := range stats.roadCoverage {
		report.RoadCoverage[value] += count
	}
	if stats.speedCount == 0 {
		return
	}
	if report.MinimumSpeedKPH == nil || stats.minimumSpeed < *report.MinimumSpeedKPH {
		value := stats.minimumSpeed
		report.MinimumSpeedKPH = &value
	}
	if report.MaximumSpeedKPH == nil || stats.maximumSpeed > *report.MaximumSpeedKPH {
		value := stats.maximumSpeed
		report.MaximumSpeedKPH = &value
	}
	if report.AverageSpeedKPH == nil {
		value := 0.0
		report.AverageSpeedKPH = &value
	}
	// Temporarily hold the total in AverageSpeedKPH; finish divides by count.
	*report.AverageSpeedKPH += stats.totalSpeed
}

func (report *zoomReport) finish() {
	if report.AverageSpeedKPH == nil {
		return
	}
	speedCount := report.TrafficFeatures - report.FeaturesWithoutSpeed
	if speedCount > 0 {
		*report.AverageSpeedKPH /= float64(speedCount)
	}
}

func loadOrFetchTile(
	ctx context.Context,
	client *http.Client,
	apiKey string,
	margin float64,
	tile tile,
	directory string,
) ([]byte, bool, error) {
	if directory != "" {
		path := tilePath(directory, margin, tile)
		data, err := os.ReadFile(path)
		if err == nil {
			if len(data) > maximumTileBytes {
				return nil, false, fmt.Errorf("cached tile %d/%d/%d exceeds %d bytes", tile.Z, tile.X, tile.Y, maximumTileBytes)
			}
			return data, true, nil
		}
		if !errors.Is(err, os.ErrNotExist) {
			return nil, false, fmt.Errorf("read cached tile %d/%d/%d: %w", tile.Z, tile.X, tile.Y, err)
		}
	}

	data, err := fetchTile(ctx, client, apiKey, margin, tile)
	if err != nil {
		return nil, false, err
	}
	if directory != "" {
		if err := saveTile(directory, margin, tile, data); err != nil {
			return nil, false, err
		}
	}
	return data, false, nil
}

func saveTile(directory string, margin float64, tile tile, data []byte) error {
	if err := os.MkdirAll(directory, 0o750); err != nil {
		return fmt.Errorf("create output directory: %w", err)
	}
	if err := os.WriteFile(tilePath(directory, margin, tile), data, 0o600); err != nil {
		return fmt.Errorf("write tile %d/%d/%d: %w", tile.Z, tile.X, tile.Y, err)
	}
	return nil
}

func tilePath(directory string, margin float64, tile tile) string {
	marginText := strings.ReplaceAll(strconv.FormatFloat(margin, 'f', -1, 64), ".", "_")
	return filepath.Join(
		directory,
		fmt.Sprintf("flow-absolute-margin-%s-%d-%d-%d.pbf", marginText, tile.Z, tile.X, tile.Y),
	)
}

package main

import (
	"context"
	"os"
	"reflect"
	"testing"
)

func TestLoadAreaGeometrySelectsFeatureByID(t *testing.T) {
	path := t.TempDir() + "/areas.geojson"
	data := []byte(`{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"02"},"geometry":{"type":"Polygon","coordinates":[[[0,0],[1,0],[1,1],[0,0]]]}}]}`)
	if err := os.WriteFile(path, data, 0o600); err != nil {
		t.Fatalf("write area fixture: %v", err)
	}
	geometry, err := loadAreaGeometry(path, "02")
	if err != nil {
		t.Fatalf("loadAreaGeometry returned error: %v", err)
	}
	if string(geometry) != `{"type":"Polygon","coordinates":[[[0,0],[1,0],[1,1],[0,0]]]}` {
		t.Fatalf("unexpected geometry: %s", geometry)
	}
}

func TestParseZoomsSortsAndDeduplicates(t *testing.T) {
	got, err := parseZooms("16, 14,15,14")
	if err != nil {
		t.Fatalf("parseZooms returned error: %v", err)
	}
	want := []int{14, 15, 16}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("parseZooms = %v, want %v", got, want)
	}
}

func TestParseZoomsRejectsInvalidValues(t *testing.T) {
	for _, value := range []string{"", "14,no", "23"} {
		t.Run(value, func(t *testing.T) {
			if _, err := parseZooms(value); err == nil {
				t.Fatalf("parseZooms(%q) succeeded, want error", value)
			}
		})
	}
}

func TestTilesAroundObeliscoAtZoom15(t *testing.T) {
	tiles, err := tilesAround(defaultLatitude, defaultLongitude, 1000, 15)
	if err != nil {
		t.Fatalf("tilesAround returned error: %v", err)
	}
	if len(tiles) < 4 || len(tiles) > 16 {
		t.Fatalf("tilesAround returned %d tiles, expected a small local grid", len(tiles))
	}
	for _, tile := range tiles {
		if tile.Z != 15 {
			t.Fatalf("tile zoom = %d, want 15", tile.Z)
		}
	}
}

func TestLoadOrFetchTileUsesReadThroughCache(t *testing.T) {
	directory := t.TempDir()
	tile := tile{X: 1, Y: 2, Z: 14}
	want := []byte("cached-pbf")
	if err := os.WriteFile(tilePath(directory, 0.1, tile), want, 0o600); err != nil {
		t.Fatalf("write cached tile: %v", err)
	}

	got, cacheHit, err := loadOrFetchTile(
		context.Background(),
		nil,
		"unused-key",
		0.1,
		tile,
		directory,
	)
	if err != nil {
		t.Fatalf("loadOrFetchTile returned error: %v", err)
	}
	if !cacheHit {
		t.Fatal("loadOrFetchTile cacheHit = false, want true")
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("loadOrFetchTile data = %q, want %q", got, want)
	}
}

func TestRedactSecretRemovesPlainAndEscapedKey(t *testing.T) {
	const key = "secret+key/value"
	message := "plain=secret+key/value encoded=secret%2Bkey%2Fvalue"
	got := redactSecret(message, key)
	if got != "plain=[REDACTED] encoded=[REDACTED]" {
		t.Fatalf("redactSecret = %q", got)
	}
}

func TestParseOptionsUsesSafeDefaults(t *testing.T) {
	got, err := parseOptions(nil)
	if err != nil {
		t.Fatalf("parseOptions returned error: %v", err)
	}
	if got.radius != defaultRadius || got.margin != defaultMargin {
		t.Fatalf("unexpected defaults: %#v", got)
	}
	if !reflect.DeepEqual(got.zooms, []int{14, 15, 16}) {
		t.Fatalf("default zooms = %v", got.zooms)
	}
}

package demand

import (
	"context"
	"fmt"
	"sort"

	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/route"
)

// Repository provides the spatial candidates and aggregated demand required by
// the demand estimator.
type Repository interface {
	FindCellCandidates(
		ctx context.Context,
		input route.Route,
		radiusMeters float64,
	) ([]CellCandidate, error)
	FindDemandByStopPair(
		ctx context.Context,
		cells []AssignedCell,
	) ([]StopPairDemand, error)
}

// Service estimates potential demand.
type Service struct {
	repository              Repository
	radiusMeters            float64
	accessibilityCalculator AccessibilityCalculator
}

// NewService creates a demand estimator.
func NewService(
	repository Repository,
	radiusMeters float64,
	accessibilityCalculator AccessibilityCalculator,
) *Service {
	return &Service{
		repository:              repository,
		radiusMeters:            radiusMeters,
		accessibilityCalculator: accessibilityCalculator,
	}
}

// Estimate calculates potential demand for one validated ordered route.
func (service *Service) Estimate(
	ctx context.Context,
	input route.Route,
) (Result, error) {
	candidates, err := service.repository.FindCellCandidates(
		ctx,
		input,
		service.radiusMeters,
	)
	if err != nil {
		return Result{}, fmt.Errorf("find cell candidates: %w", err)
	}

	assignedCells := assignCells(
		candidates,
		service.radiusMeters,
		service.accessibilityCalculator,
	)
	pairDemand, err := service.repository.FindDemandByStopPair(ctx, assignedCells)
	if err != nil {
		return Result{}, fmt.Errorf("find demand by stop pair: %w", err)
	}

	result := Result{ByStopPair: pairDemand}
	for _, pair := range pairDemand {
		result.GrossDemand += pair.GrossDemand
		result.PotentialDemand += pair.PotentialDemand
	}
	return result, nil
}

func assignCells(
	candidates []CellCandidate,
	radiusMeters float64,
	accessibilityCalculator AccessibilityCalculator,
) []AssignedCell {
	selected := make(map[CellID]CellCandidate, len(candidates))
	for _, candidate := range candidates {
		current, exists := selected[candidate.CellID]
		if !exists || candidatePrecedes(candidate, current) {
			selected[candidate.CellID] = candidate
		}
	}

	result := make([]AssignedCell, 0, len(selected))
	for _, candidate := range selected {
		result = append(result, AssignedCell{
			StopOrder: candidate.StopOrder,
			StopID:    candidate.StopID,
			CellID:    candidate.CellID,
			Accessibility: accessibilityCalculator.Calculate(
				candidate.DistanceMeters,
				radiusMeters,
			),
		})
	}
	sort.Slice(result, func(left, right int) bool {
		if result[left].StopOrder != result[right].StopOrder {
			return result[left].StopOrder < result[right].StopOrder
		}
		if result[left].CellID != result[right].CellID {
			return result[left].CellID < result[right].CellID
		}
		return result[left].StopID < result[right].StopID
	})
	return result
}

func candidatePrecedes(candidate, current CellCandidate) bool {
	if candidate.DistanceMeters != current.DistanceMeters {
		return candidate.DistanceMeters < current.DistanceMeters
	}
	if candidate.StopOrder != current.StopOrder {
		return candidate.StopOrder < current.StopOrder
	}
	return candidate.StopID < current.StopID
}

package traveltime

import (
	"context"
	"fmt"
	"math"
	"sort"

	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/route"
)

// Service estimates distance and commercial travel time by route segment.
type Service struct {
	repository Repository
	policy     Policy
}

// NewService creates a travel-time estimator.
func NewService(repository Repository, policy Policy) *Service {
	return &Service{repository: repository, policy: policy}
}

// Estimate measures and estimates one validated route.
func (service *Service) Estimate(
	ctx context.Context,
	input route.Route,
) (Result, error) {
	estimates, err := service.resolveLocalPaces(ctx, segmentsFromRoute(input))
	if err != nil {
		return Result{}, err
	}

	result := Result{
		Confidence: ConfidenceHigh,
		BySegment:  make([]SegmentResult, 0, len(estimates)),
	}
	var global *GlobalPaces
	for _, estimate := range estimates {
		paces := estimate.paces
		source := estimate.source
		confidence := estimate.confidence
		referenceCount := estimate.referenceCount
		if !estimate.found {
			if global == nil {
				fallback, fallbackErr := service.repository.FindGlobalPaces(
					ctx,
					service.policy,
				)
				if fallbackErr != nil {
					return Result{}, fmt.Errorf(
						"find global commercial paces: %w",
						fallbackErr,
					)
				}
				if !validPaces(fallback.Paces) || fallback.RouteCount <= 0 {
					return Result{}, fmt.Errorf(
						"find global commercial paces: no valid GTFS references",
					)
				}
				global = &fallback
			}
			paces = global.Paces
			source = SourceGlobal
			confidence = ConfidenceLow
			referenceCount = global.RouteCount
		}

		length := estimate.lengthMeters
		segmentResult := SegmentResult{
			OriginStopID:        estimate.segment.OriginStopID,
			DestinationStopID:   estimate.segment.DestinationStopID,
			DistanceMeters:      length,
			OffPeakSeconds:      estimatedSeconds(length, paces.OffPeak),
			TypicalSeconds:      estimatedSeconds(length, paces.Typical),
			PeakSeconds:         estimatedSeconds(length, paces.Peak),
			Confidence:          confidence,
			ReferenceRouteCount: referenceCount,
			Source:              source,
		}
		result.TotalDistanceMeters += segmentResult.DistanceMeters
		result.OffPeakSeconds += segmentResult.OffPeakSeconds
		result.TypicalSeconds += segmentResult.TypicalSeconds
		result.PeakSeconds += segmentResult.PeakSeconds
		result.Confidence = worseConfidence(result.Confidence, confidence)
		result.BySegment = append(result.BySegment, segmentResult)
	}
	return result, nil
}

func segmentsFromRoute(input route.Route) []Segment {
	segments := make([]Segment, 0, len(input.Stops)-1)
	for index := 0; index < len(input.Stops)-1; index++ {
		segments = append(segments, Segment{
			Order:             index,
			OriginStopID:      input.Stops[index].ID,
			DestinationStopID: input.Stops[index+1].ID,
			Path:              *input.Stops[index].PathToNext,
		})
	}
	return segments
}

// segmentEstimate is the local commercial pace chosen for one input segment.
type segmentEstimate struct {
	segment        Segment
	lengthMeters   float64
	paces          Paces
	source         ReferenceSource
	confidence     Confidence
	referenceCount int
	found          bool
}

// resolveLocalPaces queries one corridor radius at a time, widening the search
// only for the segments that no narrower radius could resolve.
//
// An estimate keeps the first radius that reaches MinimumReferenceRoutes, so
// asking for every radius at once measures corridors that are then discarded.
// The widest radius is also by far the most expensive to measure, which makes
// that discarded work the dominant cost of a simulation.
func (service *Service) resolveLocalPaces(
	ctx context.Context,
	segments []Segment,
) ([]segmentEstimate, error) {
	if len(service.policy.ReferenceRadiiMeters) == 0 {
		return nil, fmt.Errorf("measure route segments: policy has no reference radii")
	}

	estimates := make([]segmentEstimate, len(segments))
	for index, segment := range segments {
		estimates[index] = segmentEstimate{segment: segment}
	}

	pending := segments
	for radiusIndex, radius := range service.policy.ReferenceRadiiMeters {
		if len(pending) == 0 {
			break
		}
		measured, err := service.repository.FindSegmentReferences(
			ctx,
			pending,
			service.policy,
			radius,
		)
		if err != nil {
			return nil, fmt.Errorf("find segment references: %w", err)
		}
		ordered, err := orderMeasuredSegments(measured, pending)
		if err != nil {
			return nil, err
		}

		isLastRadius := radiusIndex == len(service.policy.ReferenceRadiiMeters)-1
		unresolved := make([]Segment, 0, len(pending))
		for _, segment := range ordered {
			estimate := &estimates[segment.Order]
			estimate.lengthMeters = segment.LengthMeters

			paces, source, confidence, count, found :=
				service.pacesAtRadius(segment, radius, isLastRadius)
			if !found {
				unresolved = append(unresolved, estimate.segment)
				continue
			}
			estimate.paces = paces
			estimate.source = source
			estimate.confidence = confidence
			estimate.referenceCount = count
			estimate.found = true
		}
		pending = unresolved
	}
	return estimates, nil
}

// orderMeasuredSegments returns the measurements in the order they were
// requested and rejects a repository that answers with a different set.
func orderMeasuredSegments(
	measured []MeasuredSegment,
	requested []Segment,
) ([]MeasuredSegment, error) {
	if len(measured) != len(requested) {
		return nil, fmt.Errorf(
			"measure route segments: got %d segments, want %d",
			len(measured),
			len(requested),
		)
	}
	positions := make(map[int]int, len(requested))
	for position, segment := range requested {
		positions[segment.Order] = position
	}

	ordered := make([]MeasuredSegment, len(requested))
	seen := make([]bool, len(requested))
	for _, segment := range measured {
		position, wasRequested := positions[segment.Order]
		if !wasRequested || seen[position] {
			return nil, fmt.Errorf(
				"measure route segments: invalid segment order %d",
				segment.Order,
			)
		}
		if segment.LengthMeters <= 0 {
			return nil, fmt.Errorf(
				"measure route segments: segment %d has non-positive length",
				segment.Order,
			)
		}
		seen[position] = true
		ordered[position] = segment
	}
	return ordered, nil
}

func (service *Service) pacesAtRadius(
	segment MeasuredSegment,
	radiusMeters float64,
	isLastRadius bool,
) (Paces, ReferenceSource, Confidence, int, bool) {
	routes := consolidateRoutes(segment, radiusMeters)
	if len(routes) < service.policy.MinimumReferenceRoutes &&
		!(isLastRadius && len(routes) > 0) {
		return Paces{}, "", "", 0, false
	}

	paces := Paces{
		OffPeak: weightedMedian(routes, func(value routePace) float64 {
			return value.Paces.OffPeak
		}),
		Typical: weightedMedian(routes, func(value routePace) float64 {
			return value.Paces.Typical
		}),
		Peak: weightedMedian(routes, func(value routePace) float64 {
			return value.Paces.Peak
		}),
	}
	if !validPaces(paces) {
		return Paces{}, "", "", 0, false
	}
	return paces, sourceForRadius(radiusMeters),
		confidenceFor(radiusMeters, len(routes)), len(routes), true
}

type routePace struct {
	RouteID int64
	Paces   Paces
	Weight  float64
}

type paceAccumulator struct {
	weightedOffPeak float64
	weightedTypical float64
	weightedPeak    float64
	weight          float64
}

func consolidateRoutes(
	segment MeasuredSegment,
	radiusMeters float64,
) []routePace {
	accumulators := make(map[int64]paceAccumulator)
	for _, reference := range segment.References {
		if reference.RadiusMeters != radiusMeters ||
			!validPaces(reference.Paces) ||
			reference.OverlapMeters <= 0 ||
			reference.DistanceMeters < 0 {
			continue
		}
		overlapRatio := math.Min(
			1,
			reference.OverlapMeters/segment.LengthMeters,
		)
		proximityWeight := 1 / (1 + reference.DistanceMeters/radiusMeters)
		weight := overlapRatio * proximityWeight
		if weight <= 0 {
			continue
		}

		current := accumulators[reference.RouteID]
		current.weightedOffPeak += reference.Paces.OffPeak * weight
		current.weightedTypical += reference.Paces.Typical * weight
		current.weightedPeak += reference.Paces.Peak * weight
		current.weight += weight
		accumulators[reference.RouteID] = current
	}

	result := make([]routePace, 0, len(accumulators))
	for routeID, accumulator := range accumulators {
		if accumulator.weight <= 0 {
			continue
		}
		result = append(result, routePace{
			RouteID: routeID,
			Paces: Paces{
				OffPeak: accumulator.weightedOffPeak / accumulator.weight,
				Typical: accumulator.weightedTypical / accumulator.weight,
				Peak:    accumulator.weightedPeak / accumulator.weight,
			},
			Weight: math.Min(accumulator.weight, 1),
		})
	}
	sort.Slice(result, func(left, right int) bool {
		return result[left].RouteID < result[right].RouteID
	})
	return result
}

func weightedMedian(
	values []routePace,
	value func(routePace) float64,
) float64 {
	ordered := append([]routePace(nil), values...)
	sort.SliceStable(ordered, func(left, right int) bool {
		leftValue := value(ordered[left])
		rightValue := value(ordered[right])
		if leftValue != rightValue {
			return leftValue < rightValue
		}
		return ordered[left].RouteID < ordered[right].RouteID
	})

	var totalWeight float64
	for _, item := range ordered {
		totalWeight += item.Weight
	}
	threshold := totalWeight / 2
	var cumulative float64
	for _, item := range ordered {
		cumulative += item.Weight
		if cumulative >= threshold {
			return value(item)
		}
	}
	return value(ordered[len(ordered)-1])
}

func validPaces(paces Paces) bool {
	return paces.OffPeak > 0 &&
		paces.OffPeak <= paces.Typical &&
		paces.Typical <= paces.Peak &&
		!math.IsNaN(paces.OffPeak) &&
		!math.IsNaN(paces.Typical) &&
		!math.IsNaN(paces.Peak) &&
		!math.IsInf(paces.OffPeak, 0) &&
		!math.IsInf(paces.Typical, 0) &&
		!math.IsInf(paces.Peak, 0)
}

func estimatedSeconds(distanceMeters, secondsPerMeter float64) int64 {
	return max(1, int64(math.Round(distanceMeters*secondsPerMeter)))
}

func sourceForRadius(radiusMeters float64) ReferenceSource {
	switch radiusMeters {
	case 100:
		return SourceLocal100
	case 300:
		return SourceLocal300
	default:
		return SourceLocal800
	}
}

func confidenceFor(radiusMeters float64, routeCount int) Confidence {
	if radiusMeters == 100 && routeCount >= 3 {
		return ConfidenceHigh
	}
	if routeCount >= 3 && radiusMeters <= 800 {
		return ConfidenceMedium
	}
	return ConfidenceLow
}

func worseConfidence(left, right Confidence) Confidence {
	rank := map[Confidence]int{
		ConfidenceHigh:   3,
		ConfidenceMedium: 2,
		ConfidenceLow:    1,
	}
	if rank[right] < rank[left] {
		return right
	}
	return left
}

