// Package detour defines the domain rules used to build a temporary route
// around one road cut.
package detour

import (
	"context"
	"time"

	"github.com/ManuelGarciaF/vialis-motor/internal/simulation"
	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/route"
)

// Criterion selects the lexicographic objective used to choose a detour.
type Criterion string

const (
	CriterionShortestTime Criterion = "MENOR_TIEMPO"
	CriterionFewestLostStops Criterion = "MENOR_PARADAS_PERDIDAS"
)

// Cut is the single WGS 84 barrier supplied for a detour request.
type Cut struct {
	LineString route.LineString
}

// Input contains the route, its single cut, and the selection criterion.
type Input struct {
	Route     route.Route
	Cut       Cut
	Criterion Criterion
}

// StopAvailability describes whether a variant may retain a stop.
type StopAvailability string

const (
	StopForcedUnavailable StopAvailability = "forced_unavailable"
	StopOptional          StopAvailability = "optional"
	StopRequired          StopAvailability = "required"
)

// ClassifiedStop is one input stop classified by its distance from the cut.
type ClassifiedStop struct {
	Order          int
	ID             string
	DistanceMeters float64
	Availability   StopAvailability
}

// Connection is one directed path in the ordered stop DAG. A connection from
// i to j omits every stop strictly between i and j.
type Connection struct {
	FromStopOrder int
	ToStopOrder   int
	TravelSeconds float64
	EdgeIDs       []int64
	Path          route.LineString
}

// RoutingInput is the domain request passed to the road-network repository.
type RoutingInput struct {
	Route route.Route
	Cut   Cut
	Stops []ClassifiedStop
}

// Selection is the winning path through the ordered stop DAG.
type Selection struct {
	KeptStopOrders    []int
	OmittedStopOrders []int
	TravelSeconds     float64
	Connections       []Connection
}

// Plan is the pure routing decision produced before reconstructing and
// evaluating a complete route variant.
type Plan struct {
	Stops     []ClassifiedStop
	Selection Selection
}

// TrafficSnapshot identifies the traffic data used to price road edges. Tile
// payloads remain an infrastructure concern and are intentionally absent.
type TrafficSnapshot struct {
	FetchedAt       time.Time
	MaximumAge      time.Duration
	Zoom            int
	TileCount       int
	CacheHitCount   int
	CacheMissCount  int
}

// Variant is a reconstructed route and the current-traffic cost used to select
// it. The cost is not the GTFS commercial travel time.
type Variant struct {
	Route                   route.Route
	DecisionTravelSeconds   float64
	OmittedStops            []UncoveredStop
}

// UncoveredStop records a stop absent from the selected variant.
type UncoveredStop struct {
	Order        int
	ID           string
	Forced       bool
	DistanceMeters float64
}

// Tile identifies one Web Mercator traffic tile.
type Tile struct {
	Zoom int
	X    int
	Y    int
}

// Repository supplies graph-dependent operations. Its implementation belongs
// to the PostgreSQL adapter; domain tests use fakes.
type Repository interface {
	CutIntersectsGraph(ctx context.Context, cut Cut) (bool, error)
	FindConnections(ctx context.Context, input RoutingInput) ([]Connection, error)
}

// TrafficProvider obtains one logical snapshot for a deterministic tile set.
type TrafficProvider interface {
	Snapshot(ctx context.Context, tiles []Tile) (TrafficSnapshot, error)
}

// Comparator evaluates the original and reconstructed routes with the stable
// simulation model.
type Comparator interface {
	Compare(ctx context.Context, input simulation.ComparisonInput) (simulation.Comparison, error)
}

package detour

// Policy contains versioned model limits and geographic thresholds. Distances
// are metres and boundaries are inclusive unless the field says otherwise.
type Policy struct {
	ForbiddenCorridorMeters   float64
	ForcedStopRadiusMeters    float64
	OptionalStopRadiusMeters  float64
	SearchRadiusMeters        float64
	MaximumCutPositions       int
	MaximumCutLengthMeters    float64
	MaximumTrafficTiles       int
	TrafficZoom               int
}

func (policy Policy) validate() error {
	if policy.ForbiddenCorridorMeters <= 0 ||
		policy.ForcedStopRadiusMeters <= 0 ||
		policy.OptionalStopRadiusMeters < policy.ForcedStopRadiusMeters ||
		policy.SearchRadiusMeters < policy.OptionalStopRadiusMeters ||
		policy.MaximumCutPositions < 2 ||
		policy.MaximumCutLengthMeters <= 0 ||
		policy.MaximumTrafficTiles <= 0 ||
		policy.TrafficZoom < 0 {
		return &ValidationError{
			Field:   "policy",
			Message: "contains incoherent detour limits",
		}
	}
	return nil
}

package detour

import "fmt"

// ErrorCode is a stable machine-readable detour failure code.
type ErrorCode string

const (
	ErrorInvalidCut                  ErrorCode = "invalid_cut"
	ErrorCutOutsideGraph             ErrorCode = "cut_outside_graph"
	ErrorCutNotMatched               ErrorCode = "cut_not_matched"
	ErrorRouteNotAffected            ErrorCode = "route_not_affected"
	ErrorAnchorNotMatched            ErrorCode = "anchor_not_matched"
	ErrorRequiredStopNotMatched      ErrorCode = "required_stop_not_matched"
	ErrorNoDetourWithinSearchArea    ErrorCode = "no_detour_within_search_area"
	ErrorTrafficUnavailable          ErrorCode = "traffic_unavailable"
	ErrorTrafficStale                ErrorCode = "traffic_stale"
	ErrorTrafficCoverageInsufficient ErrorCode = "traffic_coverage_insufficient"
	ErrorTrafficTileLimitExceeded    ErrorCode = "traffic_tile_limit_exceeded"
)

// ErrorKind distinguishes invalid input, a legitimate lack of a solution, and
// an unavailable dependency without relying on HTTP status codes.
type ErrorKind string

const (
	ErrorKindInvalidInput ErrorKind = "invalid_input"
	ErrorKindNoSolution   ErrorKind = "no_solution"
	ErrorKindDependency   ErrorKind = "dependency_failure"
)

// Error is a typed domain failure. Cause is for internal wrapping and must not
// be serialized directly because provider errors may contain sensitive data.
type Error struct {
	Code    ErrorCode
	Kind    ErrorKind
	Message string
	Cause   error
}

func (err *Error) Error() string {
	if err.Message == "" {
		return string(err.Code)
	}
	return fmt.Sprintf("%s: %s", err.Code, err.Message)
}

func (err *Error) Unwrap() error { return err.Cause }

// ValidationError reports an invalid detour field that is not specific to the
// cut geometry, such as an unknown selection criterion.
type ValidationError struct {
	Field   string
	Message string
}

func (err *ValidationError) Error() string {
	return fmt.Sprintf("%s: %s", err.Field, err.Message)
}

func invalidCut(message string) error {
	return &Error{
		Code:    ErrorInvalidCut,
		Kind:    ErrorKindInvalidInput,
		Message: message,
	}
}

package detour

import (
	"fmt"
	"math"

	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/route"
)

const earthRadiusMeters = 6371008.8

// ValidateCut checks every limit that does not require the road-network
// database. Graph coverage is checked separately through Repository.
func ValidateCut(cut Cut, policy Policy) error {
	positions := cut.LineString.Positions
	if len(positions) < 2 {
		return invalidCut("cut.coordinates must contain at least two positions")
	}
	if len(positions) > policy.MaximumCutPositions {
		return invalidCut(fmt.Sprintf(
			"cut.coordinates must contain at most %d positions",
			policy.MaximumCutPositions,
		))
	}

	var lengthMeters float64
	for index, position := range positions {
		if !finite(position.Latitude) || position.Latitude < -90 || position.Latitude > 90 {
			return invalidCut(fmt.Sprintf(
				"cut.coordinates[%d].latitude must be between -90 and 90",
				index,
			))
		}
		if !finite(position.Longitude) || position.Longitude < -180 || position.Longitude > 180 {
			return invalidCut(fmt.Sprintf(
				"cut.coordinates[%d].longitude must be between -180 and 180",
				index,
			))
		}
		if index == 0 {
			continue
		}

		segmentLength := route.DistanceMeters(positions[index-1], position)
		if segmentLength == 0 {
			return invalidCut(fmt.Sprintf(
				"cut.coordinates[%d] must differ from the previous position",
				index,
			))
		}
		lengthMeters += segmentLength
		if lengthMeters > policy.MaximumCutLengthMeters {
			return invalidCut(fmt.Sprintf(
				"cut length must not exceed %.0f meters",
				policy.MaximumCutLengthMeters,
			))
		}
	}
	return nil
}

// ClassifyStops applies the forced, optional, and required stop radii to an
// already validated cut. Distance is measured to the closest great-circle
// segment rather than to its vertices.
func ClassifyStops(
	input route.Route,
	cut Cut,
	policy Policy,
) []ClassifiedStop {
	result := make([]ClassifiedStop, len(input.Stops))
	for index, stop := range input.Stops {
		distance := distanceToLineString(stop.Position, cut.LineString)
		availability := StopRequired
		switch {
		case distance <= policy.ForcedStopRadiusMeters:
			availability = StopForcedUnavailable
		case distance <= policy.OptionalStopRadiusMeters:
			availability = StopOptional
		}
		result[index] = ClassifiedStop{
			Order:          index,
			ID:             stop.ID,
			DistanceMeters: distance,
			Availability:   availability,
		}
	}
	return result
}

func distanceToLineString(point route.Position, line route.LineString) float64 {
	minimum := math.Inf(1)
	for index := 0; index < len(line.Positions)-1; index++ {
		distance := distanceToSegment(
			point,
			line.Positions[index],
			line.Positions[index+1],
		)
		minimum = math.Min(minimum, distance)
	}
	return minimum
}

// distanceToSegment measures the shortest spherical distance to the minor
// great-circle arc from start to end. Cuts are limited to 20 km, so the arc is
// unambiguous and never approaches the antipodal singularity.
func distanceToSegment(point, start, end route.Position) float64 {
	segmentAngular := route.DistanceMeters(start, end) / earthRadiusMeters
	startToPointAngular := route.DistanceMeters(start, point) / earthRadiusMeters
	if segmentAngular == 0 || startToPointAngular == 0 {
		return startToPointAngular * earthRadiusMeters
	}

	startBearing := initialBearing(start, end)
	pointBearing := initialBearing(start, point)
	bearingDelta := pointBearing - startBearing
	crossTrack := math.Asin(clamp(
		math.Sin(startToPointAngular)*math.Sin(bearingDelta),
		-1,
		1,
	))
	alongTrack := math.Atan2(
		math.Sin(startToPointAngular)*math.Cos(bearingDelta),
		math.Cos(startToPointAngular),
	)
	if alongTrack >= 0 && alongTrack <= segmentAngular {
		return math.Abs(crossTrack) * earthRadiusMeters
	}
	return math.Min(
		route.DistanceMeters(point, start),
		route.DistanceMeters(point, end),
	)
}

func initialBearing(from, to route.Position) float64 {
	fromLatitude := radians(from.Latitude)
	toLatitude := radians(to.Latitude)
	longitudeDelta := radians(to.Longitude - from.Longitude)
	return math.Atan2(
		math.Sin(longitudeDelta)*math.Cos(toLatitude),
		math.Cos(fromLatitude)*math.Sin(toLatitude)-
			math.Sin(fromLatitude)*math.Cos(toLatitude)*math.Cos(longitudeDelta),
	)
}

func radians(degrees float64) float64 { return degrees * math.Pi / 180 }

func clamp(value, minimum, maximum float64) float64 {
	return math.Min(maximum, math.Max(minimum, value))
}

func finite(value float64) bool {
	return !math.IsNaN(value) && !math.IsInf(value, 0)
}

package detour

import (
	"fmt"
	"math"
)

type selectionState struct {
	kept        []int
	connections []Connection
	seconds     float64
}

// Select resolves the ordered stop DAG according to the requested
// lexicographic criterion. Required stops can never be skipped and forced stops
// can never be retained.
func Select(
	stops []ClassifiedStop,
	connections []Connection,
	criterion Criterion,
) (Selection, error) {
	if err := validateCriterion(criterion); err != nil {
		return Selection{}, err
	}
	if err := validateSelectorInput(stops, connections); err != nil {
		return Selection{}, err
	}

	incoming := make(map[int][]Connection)
	for _, connection := range connections {
		incoming[connection.ToStopOrder] = append(
			incoming[connection.ToStopOrder],
			cloneConnection(connection),
		)
	}

	bestByEnd := make([]*selectionState, len(stops))
	for end := range stops {
		if stops[end].Availability == StopForcedUnavailable {
			continue
		}
		if !containsRequired(stops[:end]) {
			bestByEnd[end] = &selectionState{kept: []int{end}}
		}

		for _, connection := range incoming[end] {
			start := connection.FromStopOrder
			previous := bestByEnd[start]
			if previous == nil || containsRequired(stops[start+1:end]) {
				continue
			}
			candidate := &selectionState{
				kept:        appendCopy(previous.kept, end),
				connections: appendConnection(previous.connections, connection),
				seconds:     previous.seconds + connection.TravelSeconds,
			}
			if bestByEnd[end] == nil || statePrecedes(
				candidate,
				bestByEnd[end],
				criterion,
				end+1,
			) {
				bestByEnd[end] = candidate
			}
		}
	}

	var best *selectionState
	for end, candidate := range bestByEnd {
		if candidate == nil || len(candidate.kept) < 2 ||
			containsRequired(stops[end+1:]) {
			continue
		}
		if best == nil || statePrecedes(
			candidate,
			best,
			criterion,
			len(stops),
		) {
			best = candidate
		}
	}
	if best == nil {
		return Selection{}, &Error{
			Code:    ErrorNoDetourWithinSearchArea,
			Kind:    ErrorKindNoSolution,
			Message: "no path retains every required stop and at least two stops total",
		}
	}

	keptSet := make(map[int]struct{}, len(best.kept))
	for _, order := range best.kept {
		keptSet[order] = struct{}{}
	}
	omitted := make([]int, 0, len(stops)-len(best.kept))
	for order := range stops {
		if _, retained := keptSet[order]; !retained {
			omitted = append(omitted, order)
		}
	}
	return Selection{
		KeptStopOrders:    append([]int(nil), best.kept...),
		OmittedStopOrders: omitted,
		TravelSeconds:     best.seconds,
		Connections:       cloneConnections(best.connections),
	}, nil
}

func validateCriterion(criterion Criterion) error {
	if criterion != CriterionShortestTime && criterion != CriterionFewestLostStops {
		return &ValidationError{
			Field:   "criterion",
			Message: "must be MENOR_TIEMPO or MENOR_PARADAS_PERDIDAS",
		}
	}
	return nil
}

func validateSelectorInput(stops []ClassifiedStop, connections []Connection) error {
	for index, stop := range stops {
		if stop.Order != index {
			return fmt.Errorf("select detour: stop order %d at position %d", stop.Order, index)
		}
		switch stop.Availability {
		case StopForcedUnavailable, StopOptional, StopRequired:
		default:
			return fmt.Errorf("select detour: stop %d has invalid availability %q", index, stop.Availability)
		}
	}
	for _, connection := range connections {
		if connection.FromStopOrder < 0 ||
			connection.ToStopOrder >= len(stops) ||
			connection.FromStopOrder >= connection.ToStopOrder {
			return fmt.Errorf(
				"select detour: invalid connection %d -> %d",
				connection.FromStopOrder,
				connection.ToStopOrder,
			)
		}
		if connection.TravelSeconds < 0 ||
			math.IsNaN(connection.TravelSeconds) ||
			math.IsInf(connection.TravelSeconds, 0) {
			return fmt.Errorf(
				"select detour: connection %d -> %d has invalid travel time",
				connection.FromStopOrder,
				connection.ToStopOrder,
			)
		}
	}
	return nil
}

func containsRequired(stops []ClassifiedStop) bool {
	for _, stop := range stops {
		if stop.Availability == StopRequired {
			return true
		}
	}
	return false
}

func statePrecedes(
	candidate, current *selectionState,
	criterion Criterion,
	consideredStops int,
) bool {
	candidateOmitted := consideredStops - len(candidate.kept)
	currentOmitted := consideredStops - len(current.kept)
	if criterion == CriterionShortestTime {
		if candidate.seconds != current.seconds {
			return candidate.seconds < current.seconds
		}
		if candidateOmitted != currentOmitted {
			return candidateOmitted < currentOmitted
		}
	} else {
		if candidateOmitted != currentOmitted {
			return candidateOmitted < currentOmitted
		}
		if candidate.seconds != current.seconds {
			return candidate.seconds < current.seconds
		}
	}
	if comparison := compareInts(candidate.kept, current.kept); comparison != 0 {
		return comparison < 0
	}
	return compareInts64(
		flattenEdgeIDs(candidate.connections),
		flattenEdgeIDs(current.connections),
	) < 0
}

func compareInts(left, right []int) int {
	for index := 0; index < min(len(left), len(right)); index++ {
		if left[index] < right[index] {
			return -1
		}
		if left[index] > right[index] {
			return 1
		}
	}
	if len(left) < len(right) {
		return -1
	}
	if len(left) > len(right) {
		return 1
	}
	return 0
}

func compareInts64(left, right []int64) int {
	for index := 0; index < min(len(left), len(right)); index++ {
		if left[index] < right[index] {
			return -1
		}
		if left[index] > right[index] {
			return 1
		}
	}
	if len(left) < len(right) {
		return -1
	}
	if len(left) > len(right) {
		return 1
	}
	return 0
}

func flattenEdgeIDs(connections []Connection) []int64 {
	var result []int64
	for _, connection := range connections {
		result = append(result, connection.EdgeIDs...)
	}
	return result
}

func appendCopy(values []int, value int) []int {
	result := make([]int, len(values), len(values)+1)
	copy(result, values)
	return append(result, value)
}

func appendConnection(values []Connection, value Connection) []Connection {
	result := cloneConnections(values)
	return append(result, cloneConnection(value))
}

func cloneConnections(values []Connection) []Connection {
	result := make([]Connection, len(values))
	for index, value := range values {
		result[index] = cloneConnection(value)
	}
	return result
}

func cloneConnection(value Connection) Connection {
	value.EdgeIDs = append([]int64(nil), value.EdgeIDs...)
	value.Path.Positions = append([]route.Position(nil), value.Path.Positions...)
	return value
}

