package detour

import (
	"errors"
	"math"
	"testing"

	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/route"
)

func TestValidateCutRejectsInvalidGeometryAndLimits(t *testing.T) {
	basePolicy := testPolicy()
	tests := []struct {
		name   string
		cut    Cut
		policy Policy
	}{
		{name: "too few positions", cut: cutAt()},
		{name: "non finite", cut: cutAt(position(0, 0), position(math.NaN(), 1))},
		{name: "out of range", cut: cutAt(position(0, 0), position(91, 1))},
		{name: "zero segment", cut: cutAt(position(0, 0), position(0, 0))},
		{
			name: "too many positions",
			cut: cutAt(position(0, 0), position(0, 0.001), position(0, 0.002)),
			policy: func() Policy {
				value := basePolicy
				value.MaximumCutPositions = 2
				return value
			}(),
		},
		{
			name: "too long",
			cut:  cutAt(position(0, 0), position(0, 0.01)),
			policy: func() Policy {
				value := basePolicy
				value.MaximumCutLengthMeters = 100
				return value
			}(),
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			policy := test.policy
			if policy.MaximumCutPositions == 0 {
				policy = basePolicy
			}
			err := ValidateCut(test.cut, policy)
			var detourError *Error
			if !errors.As(err, &detourError) || detourError.Code != ErrorInvalidCut {
				t.Fatalf("ValidateCut error = %v, want invalid_cut", err)
			}
		})
	}
}

func TestClassifyStopsMeasuresClosestPointOnSegment(t *testing.T) {
	input := route.Route{Stops: []route.Stop{
		{ID: "forced", Position: position(0.00009, 0.005)},
		{ID: "optional", Position: position(0.0009, 0.005)},
		{ID: "required", Position: position(0.0054, 0.005)},
	}}
	cut := cutAt(position(0, 0), position(0, 0.01))

	got := ClassifyStops(input, cut, testPolicy())
	want := []StopAvailability{
		StopForcedUnavailable,
		StopOptional,
		StopRequired,
	}
	for index := range want {
		if got[index].Availability != want[index] {
			t.Errorf("stop %d availability = %q, want %q (distance %.2f)",
				index, got[index].Availability, want[index], got[index].DistanceMeters)
		}
	}
	if got[1].DistanceMeters < 95 || got[1].DistanceMeters > 105 {
		t.Fatalf("distance to segment = %.2f, want approximately 100 m", got[1].DistanceMeters)
	}
}

func TestDistanceToSegmentUsesEndpointOutsideArc(t *testing.T) {
	start := position(0, 0)
	end := position(0, 0.001)
	point := position(0, 0.002)

	got := distanceToSegment(point, start, end)
	want := route.DistanceMeters(point, end)
	if math.Abs(got-want) > 0.001 {
		t.Fatalf("distanceToSegment = %.6f, want endpoint distance %.6f", got, want)
	}
}

func testPolicy() Policy {
	return Policy{
		ForbiddenCorridorMeters:  5,
		ForcedStopRadiusMeters:   20,
		OptionalStopRadiusMeters: 500,
		SearchRadiusMeters:       1000,
		MaximumCutPositions:      10_000,
		MaximumCutLengthMeters:   20_000,
		MaximumTrafficTiles:      32,
		TrafficZoom:              14,
	}
}

func cutAt(positions ...route.Position) Cut {
	return Cut{LineString: route.LineString{Positions: positions}}
}

func position(latitude, longitude float64) route.Position {
	return route.Position{Latitude: latitude, Longitude: longitude}
}

package detour

import (
	"errors"
	"reflect"
	"testing"
)

func TestSelectCriteriaDivergeWithoutImplicitStopPenalty(t *testing.T) {
	stops := classified(
		StopRequired,
		StopOptional,
		StopOptional,
		StopRequired,
	)
	connections := []Connection{
		connection(0, 1, 5, 1),
		connection(1, 2, 5, 2),
		connection(2, 3, 5, 3),
		connection(0, 3, 14.9, 4),
	}

	shortest, err := Select(stops, connections, CriterionShortestTime)
	if err != nil {
		t.Fatalf("Select shortest returned error: %v", err)
	}
	if !reflect.DeepEqual(shortest.KeptStopOrders, []int{0, 3}) {
		t.Fatalf("shortest kept = %v, want [0 3]", shortest.KeptStopOrders)
	}

	fewestLost, err := Select(stops, connections, CriterionFewestLostStops)
	if err != nil {
		t.Fatalf("Select fewest lost returned error: %v", err)
	}
	if !reflect.DeepEqual(fewestLost.KeptStopOrders, []int{0, 1, 2, 3}) {
		t.Fatalf("fewest lost kept = %v, want [0 1 2 3]", fewestLost.KeptStopOrders)
	}
}

func TestSelectNeverRetainsForcedOrSkipsRequiredStops(t *testing.T) {
	stops := classified(
		StopRequired,
		StopForcedUnavailable,
		StopRequired,
		StopOptional,
	)
	connections := []Connection{
		connection(0, 2, 10, 1),
		connection(0, 3, 1, 2), // Invalid alternative: it skips required stop 2.
		connection(2, 3, 10, 3),
	}

	got, err := Select(stops, connections, CriterionShortestTime)
	if err != nil {
		t.Fatalf("Select returned error: %v", err)
	}
	if !reflect.DeepEqual(got.KeptStopOrders, []int{0, 2}) {
		t.Fatalf("kept = %v, want [0 2]", got.KeptStopOrders)
	}
	if !reflect.DeepEqual(got.OmittedStopOrders, []int{1, 3}) {
		t.Fatalf("omitted = %v, want [1 3]", got.OmittedStopOrders)
	}
}

func TestSelectAllowsOptionalTerminalStopsToBeOmitted(t *testing.T) {
	stops := classified(StopOptional, StopRequired, StopRequired, StopOptional)
	connections := []Connection{
		connection(0, 1, 100, 1),
		connection(1, 2, 10, 2),
		connection(2, 3, 100, 3),
	}

	got, err := Select(stops, connections, CriterionShortestTime)
	if err != nil {
		t.Fatalf("Select returned error: %v", err)
	}
	if !reflect.DeepEqual(got.KeptStopOrders, []int{1, 2}) {
		t.Fatalf("kept = %v, want [1 2]", got.KeptStopOrders)
	}
}

func TestSelectUsesStableEdgeIDTieBreak(t *testing.T) {
	stops := classified(StopRequired, StopRequired)
	connections := []Connection{
		connection(0, 1, 10, 9),
		connection(0, 1, 10, 3),
	}

	got, err := Select(stops, connections, CriterionShortestTime)
	if err != nil {
		t.Fatalf("Select returned error: %v", err)
	}
	if got.Connections[0].EdgeIDs[0] != 3 {
		t.Fatalf("selected edge ID = %d, want 3", got.Connections[0].EdgeIDs[0])
	}
}

func TestSelectReturnsTypedErrorWhenNoVariantExists(t *testing.T) {
	_, err := Select(
		classified(StopRequired, StopRequired),
		nil,
		CriterionShortestTime,
	)
	var detourError *Error
	if !errors.As(err, &detourError) ||
		detourError.Code != ErrorNoDetourWithinSearchArea ||
		detourError.Kind != ErrorKindNoSolution {
		t.Fatalf("Select error = %#v, want no_detour_within_search_area", err)
	}
}

func classified(values ...StopAvailability) []ClassifiedStop {
	result := make([]ClassifiedStop, len(values))
	for index, value := range values {
		result[index] = ClassifiedStop{Order: index, ID: string(rune('A' + index)), Availability: value}
	}
	return result
}

func connection(from, to int, seconds float64, edgeIDs ...int64) Connection {
	return Connection{
		FromStopOrder: from,
		ToStopOrder:   to,
		TravelSeconds: seconds,
		EdgeIDs:       edgeIDs,
	}
}

