content.text:
// Package detour defines the domain rules used to build a temporary route
// around one road cut.
package detour

import (
	"context"
	"time"

	"github.com/ManuelGarciaF/vialis-motor/internal/simulation"
	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/route"
)

// Criterion selects the lexicographic objective used to choose a detour.
type Criterion string

const (
	CriterionShortestTime    Criterion = "MENOR_TIEMPO"
	CriterionFewestLostStops Criterion = "MENOR_PARADAS_PERDIDAS"
)

// Cut is the single WGS 84 barrier supplied for a detour request.
type Cut struct {
	LineString route.LineString
}

// Input contains the route, its single cut, and the selection criterion.
type Input struct {
	Route     route.Route
	Cut       Cut
	Criterion Criterion
}

// StopAvailability describes whether a variant may retain a stop.
type StopAvailability string

const (
	StopForcedUnavailable StopAvailability = "forced_unavailable"
	StopOptional          StopAvailability = "optional"
	StopRequired          StopAvailability = "required"
)

// ClassifiedStop is one input stop classified by its distance from the cut.
type ClassifiedStop struct {
	Order          int
	ID             string
	DistanceMeters float64
	Availability   StopAvailability
}

// Connection is one directed path in the ordered stop DAG. A connection from
// i to j omits every stop strictly between i and j.
type Connection struct {
	FromStopOrder int
	ToStopOrder   int
	TravelSeconds float64
	EdgeIDs       []int64
	Path          route.LineString
}

// RoutingInput is the domain request passed to the road-network repository.
type RoutingInput struct {
	Route route.Route
	Cut   Cut
	Stops []ClassifiedStop
}

// Selection is the winning path through the ordered stop DAG.
type Selection struct {
	KeptStopOrders    []int
	OmittedStopOrders []int
	TravelSeconds     float64
	Connections       []Connection
}

// Plan is the pure routing decision produced before reconstructing and
// evaluating a complete route variant.
type Plan struct {
	Stops     []ClassifiedStop
	Selection Selection
}

// TrafficSnapshot identifies the traffic data used to price road edges. Tile
// payloads remain an infrastructure concern and are intentionally absent.
type TrafficSnapshot struct {
	FetchedAt      time.Time
	MaximumAge     time.Duration
	Zoom           int
	TileCount      int
	CacheHitCount  int
	CacheMissCount int
}

// Variant is a reconstructed route and the current-traffic cost used to select
// it. The cost is not the GTFS commercial travel time.
type Variant struct {
	Route                 route.Route
	DecisionTravelSeconds float64
	OmittedStops          []UncoveredStop
}

// UncoveredStop records a stop absent from the selected variant.
type UncoveredStop struct {
	Order          int
	ID             string
	Forced         bool
	DistanceMeters float64
}

// Tile identifies one Web Mercator traffic tile.
type Tile struct {
	Zoom int
	X    int
	Y    int
}

// Repository supplies graph-dependent operations. Its implementation belongs
// to the PostgreSQL adapter; domain tests use fakes.
type Repository interface {
	CutIntersectsGraph(ctx context.Context, cut Cut) (bool, error)
	FindConnections(ctx context.Context, input RoutingInput) ([]Connection, error)
}

// TrafficProvider obtains one logical snapshot for a deterministic tile set.
type TrafficProvider interface {
	Snapshot(ctx context.Context, tiles []Tile) (TrafficSnapshot, error)
}

// Comparator evaluates the original and reconstructed routes with the stable
// simulation model.
type Comparator interface {
	Compare(ctx context.Context, input simulation.ComparisonInput) (simulation.Comparison, error)
}

package detour

import (
	"fmt"
	"math"

	"github.com/ManuelGarciaF/vialis-motor/internal/simulation/route"
)

type selectionState struct {
	kept        []int
	connections []Connection
	seconds     float64
}

// Select resolves the ordered stop DAG according to the requested
// lexicographic criterion. Required stops can never be skipped and forced stops
// can never be retained.
func Select(
	stops []ClassifiedStop,
	connections []Connection,
	criterion Criterion,
) (Selection, error) {
	if err := validateCriterion(criterion); err != nil {
		return Selection{}, err
	}
	if err := validateSelectorInput(stops, connections); err != nil {
		return Selection{}, err
	}

	incoming := make(map[int][]Connection)
	for _, connection := range connections {
		incoming[connection.ToStopOrder] = append(
			incoming[connection.ToStopOrder],
			cloneConnection(connection),
		)
	}

	// Keep separate states for paths with one retained stop and paths with at
	// least two. Without that dimension, a zero-cost one-stop prefix could
	// discard the only state that is itself a valid route.
	bestByEnd := make([][2]*selectionState, len(stops))
	for end := range stops {
		if stops[end].Availability == StopForcedUnavailable {
			continue
		}
		if !containsRequired(stops[:end]) {
			bestByEnd[end][0] = &selectionState{kept: []int{end}}
		}

		for _, connection := range incoming[end] {
			start := connection.FromStopOrder
			if containsRequired(stops[start+1 : end]) {
				continue
			}
			for category, previous := range bestByEnd[start] {
				if previous == nil {
					continue
				}
				candidate := &selectionState{
					kept:        appendCopy(previous.kept, end),
					connections: appendConnection(previous.connections, connection),
					seconds:     previous.seconds + connection.TravelSeconds,
				}
				candidateCategory := min(1, category+1)
				current := bestByEnd[end][candidateCategory]
				if current == nil || statePrecedes(
					candidate,
					current,
					criterion,
					end+1,
				) {
					bestByEnd[end][candidateCategory] = candidate
				}
			}
		}
	}

	var best *selectionState
	for end, states := range bestByEnd {
		candidate := states[1]
		if candidate == nil || containsRequired(stops[end+1:]) {
			continue
		}
		if best == nil || statePrecedes(
			candidate,
			best,
			criterion,
			len(stops),
		) {
			best = candidate
		}
	}
	if best == nil {
		return Selection{}, &Error{
			Code:    ErrorNoDetourWithinSearchArea,
			Kind:    ErrorKindNoSolution,
			Message: "no path retains every required stop and at least two stops total",
		}
	}

	keptSet := make(map[int]struct{}, len(best.kept))
	for _, order := range best.kept {
		keptSet[order] = struct{}{}
	}
	omitted := make([]int, 0, len(stops)-len(best.kept))
	for order := range stops {
		if _, retained := keptSet[order]; !retained {
			omitted = append(omitted, order)
		}
	}
	return Selection{
		KeptStopOrders:    append([]int(nil), best.kept...),
		OmittedStopOrders: omitted,
		TravelSeconds:     best.seconds,
		Connections:       cloneConnections(best.connections),
	}, nil
}

func validateCriterion(criterion Criterion) error {
	if criterion != CriterionShortestTime && criterion != CriterionFewestLostStops {
		return &ValidationError{
			Field:   "criterion",
			Message: "must be MENOR_TIEMPO or MENOR_PARADAS_PERDIDAS",
		}
	}
	return nil
}

func validateSelectorInput(stops []ClassifiedStop, connections []Connection) error {
	for index, stop := range stops {
		if stop.Order != index {
			return fmt.Errorf("select detour: stop order %d at position %d", stop.Order, index)
		}
		switch stop.Availability {
		case StopForcedUnavailable, StopOptional, StopRequired:
		default:
			return fmt.Errorf("select detour: stop %d has invalid availability %q", index, stop.Availability)
		}
	}
	for _, connection := range connections {
		if connection.FromStopOrder < 0 ||
			connection.ToStopOrder >= len(stops) ||
			connection.FromStopOrder >= connection.ToStopOrder {
			return fmt.Errorf(
				"select detour: invalid connection %d -> %d",
				connection.FromStopOrder,
				connection.ToStopOrder,
			)
		}
		if connection.TravelSeconds < 0 ||
			math.IsNaN(connection.TravelSeconds) ||
			math.IsInf(connection.TravelSeconds, 0) {
			return fmt.Errorf(
				"select detour: connection %d -> %d has invalid travel time",
				connection.FromStopOrder,
				connection.ToStopOrder,
			)
		}
	}
	return nil
}

func containsRequired(stops []ClassifiedStop) bool {
	for _, stop := range stops {
		if stop.Availability == StopRequired {
			return true
		}
	}
	return false
}

func statePrecedes(
	candidate, current *selectionState,
	criterion Criterion,
	consideredStops int,
) bool {
	candidateOmitted := consideredStops - len(candidate.kept)
	currentOmitted := consideredStops - len(current.kept)
	if criterion == CriterionShortestTime {
		if candidate.seconds != current.seconds {
			return candidate.seconds < current.seconds
		}
		if candidateOmitted != currentOmitted {
			return candidateOmitted < currentOmitted
		}
	} else {
		if candidateOmitted != currentOmitted {
			return candidateOmitted < currentOmitted
		}
		if candidate.seconds != current.seconds {
			return candidate.seconds < current.seconds
		}
	}
	if comparison := compareInts(candidate.kept, current.kept); comparison != 0 {
		return comparison < 0
	}
	return compareInts64(
		flattenEdgeIDs(candidate.connections),
		flattenEdgeIDs(current.connections),
	) < 0
}

func compareInts(left, right []int) int {
	for index := 0; index < min(len(left), len(right)); index++ {
		if left[index] < right[index] {
			return -1
		}
		if left[index] > right[index] {
			return 1
		}
	}
	if len(left) < len(right) {
		return -1
	}
	if len(left) > len(right) {
		return 1
	}
	return 0
}

func compareInts64(left, right []int64) int {
	for index := 0; index < min(len(left), len(right)); index++ {
		if left[index] < right[index] {
			return -1
		}
